// Tab ownership: 'agent' tabs belong to one agent session; 'human' means the user is driving;
// 'unclaimed' tabs can be read and acted on by any session.
export function canAct(tab: Tab, caller: SessionId) {
  if (tab.owner === 'human') return false
  if (tab.owner === 'unclaimed') return true
  return tab.ownerSession === caller
}
